using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class ErnestHemingway
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "And how much better to die in all the happy period of undisillusioned youth, to go out in a blaze of light, than to have your body worn out and old and illusions shattered.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Switzerland is a small, steep country, much more up and down than sideways, and is all stuck over with large brown hotels built on the cuckoo clock style of architecture.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Somebody just back of you while you are fishing is as bad as someone looking over your shoulder while you write a letter to your girl.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "A man's got to take a lot of punishment to write a really funny book.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The age demanded that we dance And jammed us into iron pants. And in the end the age was handed The sort of shit that it demanded.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "My attitude toward punctuation is that it ought to be as conventional as possible. The game of golf would lose a good deal if croquet mallets and billiard cues were allowed on the putting green. You ought to be able to show that you can do it a good deal better than anyone else with the regular tools before you have a license to bring in your own improvements.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "God knows, people who are paid to have attitudes toward things, professional critics, make me sick; camp-following eunuchs of literature. They won't even whore. They're all virtuous and sterile. And how well meaning and high minded. But they're all camp-followers.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I wonder what your idea of heaven would be — A beautiful vacuum filled with wealthy monogamists. All powerful and members of the best families all drinking themselves to death. And hell would probably be an ugly vacuum full of poor polygamists unable to obtain booze or with chronic stomach disorders that they called secret sorrows.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "To me a heaven would be a big bull ring with me holding two barrera seats and a trout stream outside that no one else was allowed to fish in and two lovely houses in the town; one where I would have my wife and children and be monogamous and love them truly and well and the other where I would have my nine beautiful mistresses on 9 different floors and one house would be fitted up with special copies of the Dial printed on soft tissue and kept in the toilets on every floor and in the other house we would use the American Mercury and the New Republic.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Write me at the Hotel Quintana, Pamplona, Spain. Or don't you like to write letters. I do because it's such a swell way to keep from working and yet feel you've done something", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I've tried to reduce profanity but I reduced so much profanity when writing the book that I'm afraid not much could come out. Perhaps we will have to consider it simply as a profane book and hope that the next book will be less profane or perhaps more sacred.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "In the fall the war was always there but we did not go to it any more.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "‘It’s his sense of self-preservation.’ ‘The great Italian sense.’ ‘The greatest Italian sense.’", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The good parts of a book may be only something a writer is lucky enough to overhear or it may be the wreck of his whole damn life — and one is as good as the other.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "That terrible mood of depression of whether it's any good or not is what is known as The Artist's Reward.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Grace under pressure.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Eschew the monumental. Shun the Epic. All the guys who can paint great big pictures can paint great small ones.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "When you have shot one bird flying you have shot all birds flying. They are all different and they fly in different ways but the sensation is the same and the last one is as good as the first.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Our nada who art in nada, nada be thy name thy kingdom nada thy will be nada in nada as it is in nada. Give us this nada our daily nada and nada us our nada as we nada our nadas and nada us not into nada but deliver us from nada; pues nada. Hail nothing full of nothing, nothing is with thee.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "That is what we are supposed to do when we are at our best — make it all up — but make it up so truly that later it will happen that way.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Don't you drink? I notice you speak slightingly of the bottle. I have drunk since I was fifteen and few things have given me more pleasure. When you work hard all day with your head and know you must work again the next day what else can change your ideas and make them run on a different plane like whisky? When you are cold and wet what else can warm you? Before an attack who can say anything that gives you the momentary well-being that rum does?... The only time it isn't good for you is when you write or when you fight. You have to do that cold. But it always helps my shooting. Modern life, too, is often a mechanical oppression and liquor is the only mechanical relief.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Everyone tries to frighten you now by saying or writing that if one does not become a communist or have a Marxian viewpoint one will have no friends and be alone. They seem to think that to be alone is something dreadful; or that to not have friends is to be hated. I would rather have one honest friend than most of the friends that I have known.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I cannot be a communist now because I believe in only one thing: liberty. First, I would look after myself and do my work. Then I would care for my family. Then I would help my neighbor. But the state, I care nothing for. All the state has ever meant to me is unjust taxation... I believe in the absolute minimum of government.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "A writer is like a Gypsy. He owes no allegiance to any government. If he is a good writer, he will never like the government he lives under. His hand should be against it and its hand will always be against him. The minute anyone knows any bureaucracy well enough, he will hate it. Because the minute it passes a certain size it must be unjust.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I've seen a lot of patriots and they all died just like anybody else if it hurt bad enough and once they were dead their patriotism was only good for legends; it was bad for their prose and made them write bad poetry. If you are going to be a great patriot, i.e., loyal to any existing order of government (not one who wishes to destroy the existing for something better), you want to be killed early if your life and works won't stink.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Certainly there is no hunting like the hunting of man and those who have hunted armed men long enough and liked it, never really care for anything else thereafter.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Kilimanjaro is a snow-covered mountain 19,710 feet high, and is said to be the highest mountain in Africa. Its western summit is called by the Masai \"Ngàje Ngài,\" the House of God. Close to the western summit there is the dried and frozen carcass of a leopard. No one has explained what the leopard was seeking at that altitude.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "However you make your living is where your talent lies.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The rich were dull and they drank too much or they played too much backgammon. They were dull and they were repetitious. He remembered poor Julian and his romantic awe of them and how he had started a story once that began, \"The very rich are different from you and me.\" And how someone had said to Julian, \"Yes, they have more money.\"", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Ezra was right half the time, and when he was wrong, he was so wrong you were never in any doubt about it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Anglers have a way of romanticizing their battles with fish and of forgetting that the fish has a hook in his mouth, his gullet, or his belly and that his gameness is really an extreme of panic in which he runs, leaps, and pulls to get away until he dies. It would seem to be enough advantage to the angler that the fish has the hook in his mouth rather than the angler.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "There is only one form of government that cannot produce good writers, and that system is Fascism. For Fascism is a lie told by bullies. A writer who will not lie cannot live or work under Fascism. Because Fascism is a lie, it is condemned to literary sterility. And when it is past, it will have no history, except the bloody history of murder.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "For our dead are a part of the earth of Spain now and the earth of Spain can never die.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "As long as all our dead live in the Spanish earth, and they will live as long as the earth lives, no system of tyranny ever will prevail in Spain.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The dead do not need to rise. They are a part of the earth now and the earth can never be conquered. For the earth endureth forever...Those who have entered it honorably, and no man ever entered earth more honorably than those who died in Spain, already have achieved immortality.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "There are events which are so great that if a writer has participated in them his obligation is to write truly rather than assume the presumption of altering them with invention.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I don't like to write like God. It is only because you never do it, though, that the critics think you can't do it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Cowardice, as distinguished from panic, is almost always simply a lack of ability to suspend the functioning of the imagination.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Once we have a war there is only one thing to do. It must be won. For defeat brings worse things than any that can ever happen in war.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "In going where you have to go, and doing what you have to do, and seeing what you have to see, you dull and blunt the instrument you write with. But I would rather have it bent and dulled and know I had to put it on the grindstone again and hammer it into shape and put a whetstone to it, and know that I had something to write about, than to have it bright and shining and nothing to say, or smooth and well oiled in the closet, but unused.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "All my life I've looked at words as though I were seeing them for the first time.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "It wasn't by accident that the Gettysburg address was so short. The laws of prose writing are as immutable as those of flight, of mathematics, of physics.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "You see it's awfully hard to talk or write about your own stuff because if it is any good you yourself know about how good it is — but if you say so yourself you feel like a shit.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Do you remember how old Ford was always writing how Conrad suffered so when he wrote? How it was ''un metier de chien'' etc. Do you suffer when you write? I don't at all. Suffer like a bastard when don't write, or just before, and feel empty and fucked out afterwards. But never feel as good as while writing.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Easy writing makes hard reading.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "It's enough for you to do it once for a few men to remember you. But if you do it year after year, then many people remember you and they tell it to their children, and their children and grandchildren remember and, if it concerns books, they can read them. And if it's good enough, it will last as long as there are human beings.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Scott took LITERATURE so solemnly. He never understood that it was just writing as well as you can and finishing what you start.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I started out very quiet and I beat Mr. Turgenev. Then I trained hard and I beat Mr. de Maupassant. I've fought two draws with Mr. Stendhal, and I think I had an edge in the last one. But nobody's going to get me in any ring with Mr. Tolstoy unless I'm crazy or I keep getting better.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Wars are Spinach. Life in general is the tough part. In war all you have to do is not worry and know how to read a map and co-ordinates.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Writing and travel broaden your ass if not your mind and I like to write standing up.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I am opposed to writing about the private lives of living authors and psychoanalyzing them while they are alive. Criticism is getting all mixed up with a combination of the Junior F.B.I.-men, discards from Freud and Jung and a sort of Columnist peep-hole and missing laundry list school.... Every young English professor sees gold in them dirty sheets now. Imagine what they can do with the soiled sheets of four legal beds by the same writer and you can see why their tongues are slavering.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I still need more healthy rest in order to work at my best. My health is the main capital I have and I want to administer it intelligently.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "You know lots of criticism is written by characters who are very academic and think it is a sign you are worthless if you make jokes or kid or even clown. I wouldn't kid Our Lord if he was on the cross. But I would attempt a joke with him if I ran into him chasing the money changers out of the temple.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Then there is the other secret. There isn't any symbolysm [sic]. The sea is the sea. The old man is an old man. The boy is a boy and the fish is a fish. The shark are all sharks no better and no worse. All the symbolism that people say is shit. What goes beyond is what you see beyond when you know.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Having books published is very destructive to writing. It is even worse than making love too much. Because when you make love too much at least you get a damned clarte that is like no other light. A very clear and hollow light.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Actually if a writer needs a dictionary he should not write. He should have read the dictionary at least three times from beginning to end and then have loaned it to someone who needs it. There are only certain words which are valid and similies (bring me my dictionary) are like defective ammunition (the lowest thing I can think of at this time).", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "You know that fiction, prose rather, is possibly the roughest trade of all in writing. You do not have the reference, the old important reference. You have the sheet of blank paper, the pencil, and the obligation to invent truer than things can be true. You have to take what is not palpable and make it completely palpable and also have it seem normal and so that it can become a part of experience of the person who reads it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "As a Nobel Prize winner I cannot but regret that the award was never given to Mark Twain, nor to Henry James, speaking only of my own countrymen. Greater writers than these also did not receive the prize. I would have been happy — happier — today if the prize had been given to that beautiful writer Isak Dinesen.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I wish I could write well enough to write about aircraft. Faulkner did it very well in Pylon but you cannot do something someone else has done though you might have done it if they hadn't.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Pound's crazy. All poets are.... They have to be. You don't put a poet like Pound in the loony bin. For history's sake we shouldn't keep him there.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "It is by riding a bicycle that you learn the contours of a country best, since you have to sweat up the hills and can coast down them. ... Thus you remember them as they actually are, while in a motorcar only a high hill impresses you, and you have no such accurate remembrance of country you have driven through as you gain by riding a bicycle.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "We are all apprentices in a craft where no one ever becomes a master.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Forget your personal tragedy. We are all bitched from the start and you especially have to be hurt like hell before you can write seriously. But when you get the damned hurt use it — don't cheat with it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "If you have a success, you have it for the wrong reasons. If you become popular it is always because of the worst aspects of your work.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I learned never to empty the well of my writing, but always to stop when there was still something there in the deep part of the well, and let it refill at night from the springs that fed it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "When I have an idea, I turn down the flame, as if it were a little alcohol stove, as low as it will go. Then it explodes and that is my idea.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "You make your own luck, Gig. You know what makes a good loser? Practice.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "It's none of their business that you have to learn how to write. Let them think you were born that way.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Always do sober what you said you'd do drunk. That will teach you to keep your mouth shut!", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "All thinking men are atheists.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I have noticed that doctors who fail in the practice of medicine have a tendency to seek one another's company and aid in consultation. A doctor who cannot take out your appendix properly will recommend you to a doctor who will be unable to remove your tonsils with success.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Life isn't hard to manage when you've nothing to lose.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "I was always embarrassed by the words sacred, glorious and sacrifice and the expression in vain. We had heard them, sometimes standing in the rain almost out of earshot, so that only the shouted words came through, and had read them, on proclamations that were slapped up by billposters over other proclamations, now for a long time, and I had seen nothing sacred, and the things that were glorious had no glory and the sacrifices were like the stockyards at Chicago if nothing was done with the meat except to bury it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The world breaks everyone and afterward many are strong at the broken places. But those that will not break it kills. It kills the very good and the very gentle and the very brave impartially. If you are none of these you can be sure it will kill you too but there will be no special hurry.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "No, that is the great fallacy: the wisdom of old men. They do not grow wise. They grow careful.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "All our words from loose using have lost their edge.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Decadence is a difficult word to use since it has become little more than a term of abuse applied by critics to anything they do not yet understand or which seems to differ from their moral concepts.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Bullfighting is the only art in which the artist is in danger of death and in which the degree of brilliance in the performance is left to the fighter's honor.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Honor to a Spaniard, no matter how dishonest, is as real a thing as water, wine, or olive oil. There is honor among pickpockets and honor among whores. It is simply that the standards differ.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "But waiting for a messiah is a long business and you get many fake ones.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The individual, the great artist when he comes, uses everything that has been discovered or known about his art up to that point, being able to accept or reject in a time so short it seems that the knowledge was born with him, rather than that he takes instantly what it takes the ordinary man a lifetime to know, and then the great artist goes beyond what has been done or known and makes something of his own.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "There is no remedy for anything in life. Death is a sovereign remedy for all misfortunes.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "There is no lonelier man in death, except the suicide, than that man who has lived many years with a good wife and then outlived her. If two people love each other there can be no happy end to it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Madame, it is an old word and each one takes it new and wears it out himself. It is a word that fills with meaning as a bladder with air and the meaning goes out of it as quickly. It may be punctured as a bladder is punctured and patched and blown up again and if you have not had it it does not exist for you. All people talk of it, but those who have had it are marked by it, and I would not wish to speak of it further since of all things it is the most ridiculous to talk of and only fools go through it many times.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Madame, all stories, if continued far enough, end in death, and he is no true-story teller who would keep that from you.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "It is always a mistake to know an author.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Prose is architecture, not interior decoration, and the Baroque is over.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "If a writer of prose knows enough about what he is writing about he may omit things that he knows, and the reader, if the writer is writing truly enough, will have a feeling of those things as strongly as though the writer had stated them. The dignity of movement of an iceberg is due to only one-eighth of it being above water. A writer who omits things only because he does not know them only makes hollow places in his writing.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "A serious writer is not to be confused with a solemn writer. A serious writer may be a hawk or a buzzard or even a popinjay, but a solemn writer is always a bloody owl.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "When writing a novel a writer should create living people; people not characters. A character is a caricature.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "There are some things which cannot be learned quickly, and time, which is all we have, must be paid heavily for their acquiring. They are the very simplest things and because it takes a man's life to know them the little new that each man gets from life is very costly and the only heritage he has to leave.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "When a man is still in rebellion against death he has pleasure in taking to himself one of the Godlike attributes; that of giving it.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The great thing is to last and get your work done and see and hear and learn and understand; and write when there is something that you know; and not before; and not too damned much after.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "All good books are alike in that they are truer than if they had really happened and after you are finished reading one you will feel that all that happened to you and afterwards it all belongs to you; the good and the bad, the ecstasy, the remorse, and sorrow, the people and the places and how the weather was. If you can get so that you can give that to people, then you are a writer.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The hardest thing to do is to write straight honest prose on human beings. First you have to know the subject; then you have to know how to write. Both take a lifetime to learn, and anybody is cheating who takes politics as a way out. All the outs are too easy, and the thing itself is too hard to do.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Now a writer can make himself a nice career while he is alive by espousing a political cause, working for it, making a profession of believing in it, and if it wins he will be very well placed. All politics is a matter of working hard without reward, or with a living wage for a time, in the hope of booty later. A man can be a Fascist or a Communist and if his outfit gets in he can get to be an ambassador or have a million copies of his books printed by the Government or any of the other rewards the boys dream about.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "Personal columnists ... are jackals and no jackal has been known to live on grass once he had learned about meat — no matter who killed the meat for him.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "If the book is good, is about something that you know, and is truly written, and reading it over you see that this is so, you can let the boys yip and the noise will have that pleasant sound coyotes make on a very cold night when they are out in the snow and you are in your own cabin that you have built or paid for with your work.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "All the critics who could not make their reputations by discovering you are hoping to make them by predicting hopefully your approaching impotence, failure and general drying up of natural juices. Not a one will wish you luck or hope that you will keep on writing unless you have political affiliations in which case these will rally around and speak of you and Homer, Balzac, Zola and Link Steffens.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "No catalogue of horrors ever kept men from war. Before the war you always think that it's not you that dies. But you will die, brother, if you go to it long enough.", Author = "Ernest Hemingway" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ernest_Hemingway", Text = "The first panacea for a mismanaged nation is inflation of the currency;", Author = "Ernest Hemingway" },
        };
    }
}